from __future__ import annotations

# E501 is intentionally disabled for the embedded minified HTML/CSS/JS asset.
# ruff: noqa: E501


def dashboard_html() -> str:
    """Return a dependency-free, read-only portfolio dashboard."""
    return """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Retail Forecast Lab</title>
<style>:root{--bg:#07111f;--panel:#0d1b2d;--text:#f4f7fb;--muted:#91a4bd;--line:#203853;--cyan:#3dd9c5;--blue:#73a7ff;--amber:#ffc86b;--red:#ff7b86}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#123153 0,transparent 32rem),var(--bg);color:var(--text);font:15px/1.5 ui-sans-serif,system-ui,sans-serif}main{width:min(1180px,calc(100% - 32px));margin:auto;padding:40px 0 64px}.eyebrow{color:var(--cyan);font-size:.75rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}h1{font-size:clamp(2rem,6vw,4rem);line-height:1;margin:.35rem 0 1rem;letter-spacing:-.045em}.lede{max-width:720px;color:var(--muted);font-size:1.05rem}.notice{margin:24px 0;padding:14px 16px;border:1px solid #725d31;background:#2a2112;border-radius:12px;color:#ffe3a8}.toolbar,.kpis,.split{display:grid;gap:14px}.toolbar{grid-template-columns:1fr 1fr auto;background:#0d1b2de8;padding:16px;border:1px solid var(--line);border-radius:16px}label{display:grid;gap:5px;color:var(--muted);font-size:.78rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em}select,button{min-height:42px;border:1px solid var(--line);border-radius:9px;background:#091728;color:var(--text);padding:0 12px;font:inherit}button{align-self:end;cursor:pointer;background:var(--cyan);color:#04201c;border:0;font-weight:800}.kpis{grid-template-columns:repeat(4,1fr);margin:16px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:0 16px 50px #0003}.metric span{display:block;color:var(--muted);font-size:.75rem;text-transform:uppercase;letter-spacing:.1em}.metric strong{font-size:1.65rem}.split{grid-template-columns:1.5fr 1fr}.card h2{font-size:1rem;margin:0 0 14px}.chart{width:100%;height:310px;background:#091728;border-radius:10px}.chart text{fill:var(--muted);font-size:11px}.table-wrap{overflow:auto;max-height:430px}table{border-collapse:collapse;width:100%;min-width:700px}th,td{padding:10px 9px;border-bottom:1px solid var(--line);text-align:right;font-variant-numeric:tabular-nums}th{position:sticky;top:0;background:var(--panel);color:var(--muted);font-size:.7rem;text-transform:uppercase}th:nth-child(-n+2),td:nth-child(-n+2){text-align:left}.badge{padding:3px 8px;border-radius:99px;background:#17334c;color:var(--blue);font-size:.72rem}.empty,.error,.loading{display:grid;place-items:center;min-height:180px;color:var(--muted);text-align:center}.error{color:var(--red)}footer{margin-top:26px;color:var(--muted);font-size:.8rem}a{color:var(--cyan)}@media(max-width:800px){main{width:min(100% - 20px,1180px);padding-top:24px}.toolbar,.split{grid-template-columns:1fr}.kpis{grid-template-columns:1fr 1fr}.chart{height:260px}}@media(max-width:440px){.kpis{grid-template-columns:1fr}}</style></head>
<body><main><div class="eyebrow">ML engineering · historical replay</div><h1>Retail Forecast Lab</h1><p class="lede">Inspect a leakage-aware 14-day seasonal forecast, calibrated uncertainty and the outcomes available in monitoring.</p><div class="notice"><strong>Educational historical demo.</strong> Sales are only a demand proxy. This is not connected to a live retailer and is not validated for purchasing or inventory decisions.</div>
<section class="toolbar"><label>Forecast run<select id="run"><option value="">All runs</option></select></label><label>Product SKU<select id="sku"><option value="">All products</option></select></label><button id="refresh">Refresh data</button></section>
<section class="kpis"><div class="card metric"><span>Interval coverage</span><strong id="coverage">—</strong></div><div class="card metric"><span>WAPE</span><strong id="wape">—</strong></div><div class="card metric"><span>Normalized bias</span><strong id="bias">—</strong></div><div class="card metric"><span>Observed forecasts</span><strong id="observed">—</strong></div></section>
<section class="split"><article class="card"><h2>Forecast and calibrated interval</h2><div id="visual" class="loading">Loading forecast evidence…</div></article><article class="card"><h2>What this view proves</h2><p class="lede">The point forecast is the frozen seasonal-naive champion. Bands use development-only M2 calibration. KPIs appear only for persisted outcomes.</p><p class="lede" id="summary">Waiting for data.</p></article></section><section class="card" style="margin-top:14px"><h2>Forecast ledger</h2><div id="ledger" class="loading">Loading records…</div></section><footer>Read-only service · <a href="/docs">API contract</a> · no external analytics or assets</footer></main>
<script>const el=id=>document.getElementById(id),pct=v=>v==null?'—':`${(100*v).toFixed(1)}%`;function query(){const p=new URLSearchParams({limit:'5000'});if(el('run').value)p.set('run_id',el('run').value);if(el('sku').value)p.set('sku',el('sku').value);return p}async function read(path){const r=await fetch(path);if(!r.ok)throw Error(`API ${r.status}`);return(await r.json()).items}function options(id,values,label){const selected=el(id).value;el(id).innerHTML=`<option value="">All ${label}</option>`+[...new Set(values)].sort().map(v=>`<option>${v}</option>`).join('');el(id).value=selected}function metrics(rows){if(!rows.length){['coverage','wape','bias','observed'].forEach(id=>el(id).textContent='—');return}const actual=rows.reduce((s,r)=>s+ +r.actual,0),error=rows.reduce((s,r)=>s+ +r.absolute_error,0),bias=rows.reduce((s,r)=>s+ +r.prediction- +r.actual,0);el('coverage').textContent=pct(rows.filter(r=>r.covered).length/rows.length);el('wape').textContent=actual?pct(error/actual):'N/E';el('bias').textContent=actual?pct(bias/actual):'N/E';el('observed').textContent=rows.length}function chart(rows,seen){if(!rows.length){el('visual').innerHTML='<div class="empty">No forecasts match these filters.</div>';return}rows=[...rows].sort((a,b)=>a.forecast_date.localeCompare(b.forecast_date)).slice(0,60);const W=760,H=300,P=34,max=Math.max(1,...rows.flatMap(r=>[+r.upper,+r.prediction])),x=i=>P+i*(W-2*P)/Math.max(1,rows.length-1),y=v=>H-P-v*(H-2*P)/max,path=f=>rows.map((r,i)=>`${i?'L':'M'}${x(i)},${y(+r[f])}`).join(' '),lower=[...rows].reverse().map((r,j)=>`L${x(rows.length-1-j)},${y(+r.lower)}`).join(' '),dots=rows.map((r,i)=>{const m=seen.get(`${r.run_id}|${r.sku}|${r.horizon}`);return m?`<circle cx="${x(i)}" cy="${y(+m.actual)}" r="3" fill="#ffc86b"/>`:''}).join('');el('visual').className='';el('visual').innerHTML=`<svg class="chart" role="img" aria-label="Forecast with uncertainty band" viewBox="0 0 ${W} ${H}"><path d="${path('upper')} ${lower} Z" fill="#3dd9c522"/><path d="${path('prediction')}" fill="none" stroke="#3dd9c5" stroke-width="3"/><path d="${path('upper')}" fill="none" stroke="#73a7ff"/><path d="${path('lower')}" fill="none" stroke="#73a7ff"/>${dots}<text x="34" y="20">Forecast · interval · observed</text></svg>`}function ledger(rows,seen){if(!rows.length){el('ledger').innerHTML='<div class="empty">No ledger rows for this selection.</div>';return}el('ledger').innerHTML='<div class="table-wrap"><table><thead><tr><th>Date</th><th>SKU</th><th>H</th><th>Forecast</th><th>Lower</th><th>Upper</th><th>Actual</th><th>Status</th></tr></thead><tbody>'+rows.slice(0,500).map(r=>{const m=seen.get(`${r.run_id}|${r.sku}|${r.horizon}`);return `<tr><td>${r.forecast_date}</td><td>${r.sku}</td><td>${r.horizon}</td><td>${(+r.prediction).toFixed(1)}</td><td>${(+r.lower).toFixed(1)}</td><td>${(+r.upper).toFixed(1)}</td><td>${m?(+m.actual).toFixed(1):'—'}</td><td><span class="badge">${m?'observed':'pending'}</span></td></tr>`}).join('')+'</tbody></table></div>'}async function load(){el('visual').innerHTML='<div class="loading">Loading forecast evidence…</div>';try{const q=query(),[forecasts,monitoring]=await Promise.all([read(`/api/forecasts?${q}`),read(`/api/monitoring?${q}`)]);options('run',forecasts.map(r=>r.run_id),'runs');options('sku',forecasts.map(r=>r.sku),'products');const seen=new Map(monitoring.map(r=>[`${r.run_id}|${r.sku}|${r.horizon}`,r]));metrics(monitoring);chart(forecasts,seen);ledger(forecasts,seen);el('summary').textContent=`Showing ${forecasts.length} forecasts; ${monitoring.length} have known outcomes.`}catch(e){const msg=`Unable to load demo data: ${e.message}`;el('visual').innerHTML=`<div class="error">${msg}</div>`;el('ledger').innerHTML=`<div class="error">${msg}</div>`}}['refresh','run','sku'].forEach(id=>el(id).addEventListener(id==='refresh'?'click':'change',load));load();</script></body></html>"""
